output_text:
[
  {
    "id": "no_carts_single_file_shelf_aisle",
    "text": "Carts are prohibited in single-file shelf aisles where the shopper is between shelves on both sides.",
    "abstraction": {
      "state_properties": {
        "too_narrow_for_cart": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "between_opposing_shelves": {
          "and": [
            "shelfE",
            "shelfW"
          ]
        },
        "single_file_shelf_aisle": {
          "and": [
            "too_narrow_for_cart",
            "between_opposing_shelves"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "single_file_shelf_aisle"
        ]
      }
    }
  },
  {
    "id": "no_cart_entry_single_file",
    "text": "A shopper must not enter a single-file shelf aisle while still holding a cart.",
    "abstraction": {
      "state_properties": {
        "single_file_shelf_aisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {
        "enter_single_file_with_cart": {
          "pre": {
            "and": [
              "hasCart",
              "MOVE"
            ]
          },
          "post": "single_file_shelf_aisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "enter_single_file_with_cart"
    }
  },
  {
    "id": "hands_free_service_in_single_file",
    "text": "Shelf interactions inside a single-file aisle must be performed without a cart.",
    "abstraction": {
      "state_properties": {
        "single_file_shelf_aisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "INTERACT",
          "single_file_shelf_aisle"
        ]
      }
    }
  },
  {
    "id": "park_on_arrival_at_single_file_mouth",
    "text": "After arriving with a cart at the wide mouth of a single-file shelf aisle, the shopper is obliged to park the cart before continuing.",
    "abstraction": {
      "state_properties": {
        "wide_aisle_cell": {
          "and": [
            {
              "ge": [
                "freeWidthH",
                3
              ]
            },
            {
              "ge": [
                "freeWidthV",
                3
              ]
            }
          ]
        },
        "single_file_mouth": {
          "and": [
            "at(6,3)",
            "wide_aisle_cell"
          ]
        }
      },
      "events": {
        "arrive_at_single_file_mouth_with_cart": {
          "pre": {
            "and": [
              "hasCart",
              "MOVE"
            ]
          },
          "post": "single_file_mouth"
        },
        "drop_cart_at_mouth": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT",
              "single_file_mouth"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "arrive_at_single_file_mouth_with_cart",
      "discharge": "drop_cart_at_mouth"
    }
  },
  {
    "id": "reclaim_after_leaving_single_file",
    "text": "After walking out of a single-file shelf aisle without a cart, the shopper is obliged to reclaim the cart.",
    "abstraction": {
      "state_properties": {
        "single_file_shelf_aisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {
        "leave_single_file_without_cart": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "single_file_shelf_aisle",
              "MOVE"
            ]
          },
          "post": {
            "not": "single_file_shelf_aisle"
          }
        },
        "retrieve_cart": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "leave_single_file_without_cart",
      "discharge": "retrieve_cart"
    }
  },
  {
    "id": "no_cartless_roaming_outside_exceptions",
    "text": "Movement without a cart is prohibited except in the entrance/cart-bay area, the single-file shelf aisle, or its staging mouth.",
    "abstraction": {
      "state_properties": {
        "cart_bay_area": {
          "or": [
            "at(0,7)",
            "at(1,7)"
          ]
        },
        "single_file_shelf_aisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        },
        "single_file_mouth": {
          "and": [
            "at(6,3)",
            {
              "ge": [
                "freeWidthH",
                3
              ]
            }
          ]
        },
        "permitted_cartless_area": {
          "or": [
            "cart_bay_area",
            "single_file_shelf_aisle",
            "single_file_mouth"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "MOVE",
          {
            "not": "hasCart"
          },
          {
            "not": "permitted_cartless_area"
          }
        ]
      }
    }
  },
  {
    "id": "longitudinal_only_in_single_file",
    "text": "Inside a single-file shelf aisle, shoppers must move only along the aisle's length and not laterally.",
    "abstraction": {
      "state_properties": {
        "single_file_shelf_aisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "single_file_shelf_aisle",
          {
            "or": [
              "E",
              "W"
            ]
          }
        ]
      }
    }
  },
  {
    "id": "cart_parking_only_at_staging_mouth",
    "text": "Once a cart is in use, setting it down is allowed only at the approved wide staging mouth of the single-file shelf aisle.",
    "abstraction": {
      "state_properties": {
        "wide_uncluttered_cell": {
          "and": [
            {
              "ge": [
                "freeWidthH",
                3
              ]
            },
            {
              "ge": [
                "freeWidthV",
                3
              ]
            },
            {
              "not": "adjShelf"
            }
          ]
        },
        "approved_cart_parking_spot": {
          "and": [
            "at(6,3)",
            "wide_uncluttered_cell"
          ]
        }
      },
      "events": {
        "drop_cart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "drop_cart",
          {
            "not": "approved_cart_parking_spot"
          }
        ]
      }
    }
  }
]
